CREATE SCHEMA IF NOT EXISTS smh;
SET search_path TO smh;
CREATE TABLE IF NOT EXISTS schema_version (version INTEGER PRIMARY KEY DEFAULT 1);
ALTER TABLE schema_version ALTER COLUMN version SET DEFAULT 1;
CREATE TABLE IF NOT EXISTS kv (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS trades (id TEXT PRIMARY KEY, data TEXT NOT NULL, state TEXT NOT NULL, created TEXT NOT NULL, updated TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS trades_state ON trades(state,created);
CREATE TABLE IF NOT EXISTS operations (id TEXT PRIMARY KEY, kind TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL, message_id BIGINT, created TEXT NOT NULL, updated TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS operations_status ON operations(status,created);
CREATE TABLE IF NOT EXISTS events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, trade_id TEXT REFERENCES trades(id), operation_id TEXT UNIQUE REFERENCES operations(id), actor BIGINT NOT NULL, text TEXT NOT NULL, message_id BIGINT, created TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS events_trade ON events(trade_id,id);
CREATE TABLE IF NOT EXISTS drafts (owner BIGINT PRIMARY KEY, data TEXT NOT NULL, updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS buttons (id TEXT PRIMARY KEY, owner BIGINT NOT NULL, action TEXT NOT NULL, data TEXT NOT NULL, expires DOUBLE PRECISION NOT NULL, used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS applications (user_id BIGINT PRIMARY KEY, answers TEXT NOT NULL, status TEXT NOT NULL, updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS access (user_id BIGINT REFERENCES applications(user_id), channel BIGINT NOT NULL, status TEXT NOT NULL, updated TEXT NOT NULL, PRIMARY KEY(user_id,channel));
CREATE TABLE IF NOT EXISTS errors (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category TEXT NOT NULL, detail TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assets (id TEXT PRIMARY KEY, content BYTEA NOT NULL);
CREATE TABLE IF NOT EXISTS receipts (id TEXT PRIMARY KEY REFERENCES operations(id), result TEXT NOT NULL);
INSERT INTO schema_version VALUES (1) ON CONFLICT DO NOTHING;
